// Type contract for this file (TypeScript syntax, for reference):
//
// export interface IdTokenClaims {
//   iss: string;
//   aud: string | string[];
//   sub: string;
//   nonce: string;
//   iat: number;
//   exp: number;
//   tenantId?: string;
// }
