// export interface IdTokenVerifierOptions {
//   issuer: string;
//   audience: string;
//   algorithm: string;
//   keys: Record<string, string>;
//   clockSkewMs: number;
// }
//
// export interface IdTokenVerifier {
//   verify(token: string, expectedNonce: string): IdTokenClaims | null;
// }
//
// interface TokenHeader {
//   alg?: string;
//   kid?: string;
// }

import { decodeSegment, verifyRsa } from './support/crypto';
import { now } from '@lab/env';
const SEGMENTS = 3;
/** aud may be a string or an array of strings; normalise it to one shape here */
function audienceContains(aud, expected) {
    const list = Array.isArray(aud) ? aud : [aud];
    return list.indexOf(expected) >= 0;
}
export function createIdTokenVerifier(options) {
    /** Nonces already used. One nonce corresponds to exactly one login. */
    const spentNonces = new Set();
    function publicKeyFor(header) {
        if (!header.kid)
            return null;
        const key = options.keys[header.kid];
        return typeof key === 'string' ? key : null;
    }
    function timeIsSane(claims) {
        if (typeof claims.exp !== 'number' || typeof claims.iat !== 'number')
            return false;
        if (now() >= claims.exp + options.clockSkewMs)
            return false;
        return claims.iat <= now() + options.clockSkewMs;
    }
    return {
        verify(token, expectedNonce) {
            const parts = String(token || '').split('.');
            if (parts.length !== SEGMENTS)
                return null;
            const header = decodeSegment(parts[0]);
            if (!header)
                return null;
            // The algorithm comes from our configuration. What the token claims to be does not count.
            if (header.alg !== options.algorithm)
                return null;
            const publicKey = publicKeyFor(header);
            if (!publicKey)
                return null;
            if (!verifyRsa(publicKey, parts[0] + '.' + parts[1], parts[2]))
                return null;
            const claims = decodeSegment(parts[1]);
            if (!claims)
                return null;
            if (claims.iss !== options.issuer)
                return null;
            if (!audienceContains(claims.aud, options.audience))
                return null;
            if (!timeIsSane(claims))
                return null;
            if (!expectedNonce || claims.nonce !== expectedNonce)
                return null;
            if (spentNonces.has(claims.nonce))
                return null;
            // Record the nonce only when everything passed: a failed attempt should not consume this login
            spentNonces.add(claims.nonce);
            return claims;
        },
    };
}

