  // 行宽 33：相邻行的同一列错开一个 bank，列访问不再串行
  __shared__ float tile[32][33];

  int x = threadIdx.x;
  int y = threadIdx.y;

  tile[y][x] = in[y * n + x];
  __syncthreads();
  out[y * n + x] = tile[x][y];
}

