// 4096 个数求和。
//
// 结果对，但 4096 个线程排队往同一个地址加。
// 用 __shfl_xor_sync 先在 warp 内归并，每个 warp 只出一次 atomicAdd。
__global__ void reduceSum(const float* in, float* out, int n) {
  int i = blockIdx.x * blockDim.x + threadIdx.x;
  if (i < n) {
    atomicAdd(out, in[i]);
  }
}

