__global__ void reduceSum(const float* in, float* out, int n) {
  int i = blockIdx.x * blockDim.x + threadIdx.x;
  float v = (i < n) ? in[i] : 0.0f;

  // 蝶形归并：5 步把 warp 里的 32 个值收成一个
  for (int d = 16; d > 0; d >>= 1) {
    v += __shfl_xor_sync(0xffffffff, v, d);
  }

  // 每个 warp 只出一次原子操作
  if ((threadIdx.x & 31) == 0) {
    atomicAdd(out, v);
  }
}

