// 8 抽头滑动窗口加权和。
//
// 结果是对的，但 ncu 里 Local Memory Traffic 不是 0。
//   nvcc -o bench filter.cu && ncu ./bench
__global__ void filter8(const float* in, float* out, int n) {
  int i = blockIdx.x * blockDim.x + threadIdx.x;
  if (i >= n) return;

  float tap[8];

  // 动态下标：整个 tap 数组会被搬到 local memory
  for (int k = 0; k < 8; ++k) {
    int j = i + k;
    tap[k] = (j < n) ? in[j] : 0.0f;
  }

  float acc = 0.0f;
  for (int k = 0; k < 8; ++k) {
    acc += tap[k] * (float)(k + 1);
  }
  out[i] = acc;
}

