                         int slot, int req, int dim) {
  int d = threadIdx.x;
  if (active[slot] == 0) return;
  if (d == 0) progress[req] = progress[req] + 1;
  state[slot * dim + d] = state[slot * dim + d] * 1.0009765625f + 0.001f;
