            cudaSetDevice(d);
            float one[1];
            cudaMemcpy(one, buf[d], 4, cudaMemcpyDeviceToHost);
            host[d] = one[0];
          }
          cudaSetDevice(0);
          cudaMemcpy(check, host, N * 4, cudaMemcpyHostToDevice);
