// Type contract for this file (TypeScript syntax, for reference):
//
// export interface AppendResult {
//   offset: number;
//   segmentId: number;
//   index: number;
// }
//
// export interface LogOptions {
//   segmentBytes: number;
// }
//
// export interface MessageLog {
//   append(key: string, value: string): AppendResult;
//   read(offset: number, max: number): StoredRecord[];
//   endOffset(): number;
//   segments(): SegmentInfo[];
//   flush(): Promise<void>;
// }

export function createLog(storage, options) {
    let nextOffset = 0;
    /** The active segment only needs these two numbers */
    let activeSegmentId = -1;
    let activeBytes = 0;
    function roll() {
        activeSegmentId = storage.createSegment(nextOffset);
        activeBytes = 0;
    }
    /**
     * Decide before appending: appending first and then checking leaves every segment one
     * record over
     */
    function segmentFor(size) {
        if (activeSegmentId < 0)
            roll();
        // Accept unconditionally while the segment is empty: an oversized single record still
        // needs somewhere to go
        else if (activeBytes > 0 && activeBytes + size > options.segmentBytes)
            roll();
        return activeSegmentId;
    }
    return {
        append(key, value) {
            const size = storage.sizeOf(key, value);
            const segmentId = segmentFor(size);
            const offset = nextOffset;
            const index = storage.append(segmentId, { offset, key, value });
            nextOffset += 1;
            activeBytes += size;
            return { offset, segmentId, index };
        },
        read(offset, max) {
            const found = [];
            if (max <= 0)
                return found;
            for (const segment of storage.segments()) {
                // The whole segment sits before offset, so not one record needs reading
                if (offset >= segment.baseOffset + segment.count)
                    continue;
                for (let index = 0; index < segment.count; index += 1) {
                    // The data comes from the device: whatever a power loss dropped simply is not readable here
                    const record = storage.readAt(segment.id, index);
                    if (!record)
                        break;
                    if (record.offset < offset)
                        continue;
                    found.push(record);
                    if (found.length >= max)
                        return found;
                }
            }
            return found;
        },
        endOffset() {
            return nextOffset;
        },
        segments() {
            return storage.segments();
        },
        async flush() {
            await storage.fsync();
        },
    };
}

