// Type contract for this file (TypeScript syntax, for reference):
//
// export interface IndexAnchor {
//   offset: number;
//   segmentId: number;
//   index: number;
// }
//
// export interface OffsetIndex {
//   observe(result: AppendResult): void;
//   locate(offset: number): IndexAnchor | null;
//   size(): number;
// }
//
// export interface IndexOptions {
//   indexInterval: number;
// }
//
// export interface IndexedLogOptions extends LogOptions, IndexOptions {}
//
// export interface IndexedLog extends MessageLog {
//   indexSize(): number;
//   locate(offset: number): IndexAnchor | null;
// }

import { createLog } from './log';
export function createOffsetIndex(options) {
    /** Naturally ascending by offset, because append is ascending */
    const anchors = [];
    const interval = Math.max(1, options.indexInterval);
    return {
        observe(result) {
            if (result.offset % interval !== 0)
                return;
            anchors.push({ offset: result.offset, segmentId: result.segmentId, index: result.index });
        },
        locate(offset) {
            // Binary search for the last anchor not past offset, not the closest one
            let low = 0;
            let high = anchors.length - 1;
            let found = null;
            while (low <= high) {
                const middle = Math.floor((low + high) / 2);
                if (anchors[middle].offset <= offset) {
                    found = anchors[middle];
                    low = middle + 1;
                }
                else {
                    high = middle - 1;
                }
            }
            return found;
        },
        size() {
            return anchors.length;
        },
    };
}
export function createIndexedLog(storage, options) {
    // The segment-rolling logic exists in exactly one place, back in stage 1
    const log = createLog(storage, { segmentBytes: options.segmentBytes });
    const index = createOffsetIndex({ indexInterval: options.indexInterval });
    /** Scan forward from a given index in a given segment, continuing across segments */
    function scan(anchor, offset, max) {
        const segments = storage.segments();
        const found = [];
        let start = 0;
        if (anchor) {
            const position = segments.findIndex((segment) => segment.id === anchor.segmentId);
            if (position >= 0)
                start = position;
        }
        for (let position = start; position < segments.length; position += 1) {
            const segment = segments[position];
            const from = position === start && anchor ? anchor.index : 0;
            for (let slot = from; slot < segment.count; slot += 1) {
                const record = storage.readAt(segment.id, slot);
                if (!record)
                    break;
                if (record.offset < offset)
                    continue;
                found.push(record);
                if (found.length >= max)
                    return found;
            }
        }
        return found;
    }
    return {
        append(key, value) {
            const result = log.append(key, value);
            index.observe(result);
            return result;
        },
        read(offset, max) {
            if (max <= 0)
                return [];
            return scan(index.locate(offset), offset, max);
        },
        endOffset() {
            return log.endOffset();
        },
        segments() {
            return log.segments();
        },
        async flush() {
            await log.flush();
        },
        indexSize() {
            return index.size();
        },
        locate(offset) {
            return index.locate(offset);
        },
    };
}

