// Type contract for this file (TypeScript syntax, for reference):
//
// export interface ProducerOptions {
//   batchSize: number;
//   lingerMs: number;
// }
//
// export interface ProducerStats {
//   batches: number;
//   records: number;
// }
//
// export interface Producer {
//   send(key: string, value: string): Promise<number>;
//   flush(): Promise<void>;
//   buffered(): number;
//   stats(): ProducerStats;
// }
//
// interface Pending {
//   key: string;
//   value: string;
//   settle(offset: number): void;
// }

export function createProducer(log, options) {
    let buffer = [];
    let timer = null;
    /** This chain is what keeps batches in order relative to one another */
    let chain = Promise.resolve();
    const counters = { batches: 0, records: 0 };
    function cancelTimer() {
        if (timer === null)
            return;
        clearTimeout(timer);
        timer = null;
    }
    function flushNow() {
        cancelTimer();
        // Swap the whole buffer out first, then do the async write:
        // the other way round, messages arriving during the write fall into a batch whose
        // resolves have already been handed out
        const batch = buffer;
        buffer = [];
        if (batch.length === 0)
            return chain;
        counters.batches += 1;
        counters.records += batch.length;
        chain = chain.then(async () => {
            const offsets = batch.map((entry) => log.append(entry.key, entry.value).offset);
            // One fsync for a whole batch, which amortises the fixed cost
            await log.flush();
            batch.forEach((entry, index) => entry.settle(offsets[index]));
        });
        return chain;
    }
    return {
        send(key, value) {
            return new Promise((resolve) => {
                buffer.push({ key, value, settle: resolve });
                if (buffer.length >= options.batchSize) {
                    // A full batch goes now; linger is there for the batches that never fill
                    void flushNow();
                    return;
                }
                // Only the first record of a batch starts the timer, and later ones do not push it back
                if (buffer.length === 1) {
                    timer = setTimeout(() => {
                        void flushNow();
                    }, options.lingerMs);
                }
            });
        },
        flush() {
            return flushNow();
        },
        buffered() {
            return buffer.length;
        },
        stats() {
            return { batches: counters.batches, records: counters.records };
        },
    };
}

