// Type contract for this file (TypeScript syntax, for reference):
//
// export interface DeliveryOptions {
//   visibilityMs: number;
// }
//
// export interface Delivery {
//   record: StoredRecord;
//   receipt: string;
// }
//
// export interface DeliveryQueue {
//   poll(max: number): Delivery[];
//   ack(receipt: string): boolean;
//   inflight(): number;
//   pendingOffsets(): number[];
// }
//
// interface InflightEntry {
//   record: StoredRecord;
//   receipt: string;
//   /** Becomes deliverable again if it is still unacked at this instant */
//   deadline: number;
// }

import { now } from '@lab/env';
export function createDeliveryQueue(log, options) {
    /** How far the log has been read. It only moves forward, independently of acks. */
    let cursor = 0;
    let nextReceipt = 0;
    const inflight = new Map();
    function handOut(record) {
        const receipt = 'r-' + nextReceipt;
        nextReceipt += 1;
        // Every delivery is a fresh authorisation, hence a fresh receipt
        inflight.set(receipt, { record, receipt, deadline: now() + options.visibilityMs });
        return { record, receipt };
    }
    function expired() {
        return Array.from(inflight.values()).filter((entry) => entry.deadline <= now());
    }
    return {
        poll(max) {
            const batch = [];
            if (max <= 0)
                return batch;
            // Timed-out redeliveries go first: under backlog, new messages keep arriving and the
            // old ones would otherwise never get a turn
            for (const entry of expired()) {
                if (batch.length >= max)
                    return batch;
                inflight.delete(entry.receipt);
                batch.push(handOut(entry.record));
            }
            while (batch.length < max) {
                const records = log.read(cursor, max - batch.length);
                if (records.length === 0)
                    break;
                for (const record of records) {
                    batch.push(handOut(record));
                    cursor = record.offset + 1;
                }
            }
            return batch;
        },
        ack(receipt) {
            // An expired receipt is no longer in the table, so it cannot ack anything
            return inflight.delete(receipt);
        },
        inflight() {
            return inflight.size;
        },
        pendingOffsets() {
            return Array.from(inflight.values())
                .map((entry) => entry.record.offset)
                .sort((left, right) => left - right);
        },
    };
}

