// Type contract for this file (TypeScript syntax, for reference):
//
// export interface SubscribeOptions {
//   from?: 'beginning' | 'end';
// }
//
// export interface Subscription {
//   name: string;
//   poll(max: number): StoredRecord[];
//   commit(offset: number): void;
//   seek(offset: number): void;
//   position(): number;
//   lag(): number;
// }
//
// export interface Topic {
//   publish(key: string, value: string): number;
//   subscribe(name: string, options?: SubscribeOptions): Subscription;
//   subscriptions(): string[];
//   endOffset(): number;
// }

export function createTopic(log) {
    /** A subscription's entire state is one integer here */
    const cursors = new Map();
    function positionOf(name) {
        const cursor = cursors.get(name);
        return cursor === undefined ? 0 : cursor;
    }
    function viewOf(name) {
        return {
            name,
            poll(max) {
                // Read only, without advancing: having read is not the same as having processed
                return log.read(positionOf(name), max);
            },
            commit(offset) {
                const next = offset + 1;
                // Monotonic: an old acknowledgement arriving out of order must not drag it back
                if (next > positionOf(name))
                    cursors.set(name, next);
            },
            seek(offset) {
                cursors.set(name, Math.max(0, offset));
            },
            position() {
                return positionOf(name);
            },
            lag() {
                return Math.max(0, log.endOffset() - positionOf(name));
            },
        };
    }
    return {
        publish(key, value) {
            // The only place in this whole file that writes storage, independently of the
            // subscription count
            return log.append(key, value).offset;
        },
        subscribe(name, options = {}) {
            if (!cursors.has(name)) {
                cursors.set(name, options.from === 'end' ? log.endOffset() : 0);
            }
            return viewOf(name);
        },
        subscriptions() {
            return Array.from(cursors.keys());
        },
        endOffset() {
            return log.endOffset();
        },
    };
}

