// Type contract for this file (TypeScript syntax, for reference):
//
// export interface ConsumerSink {
//   id: string;
//   deliver(record: StoredRecord): Promise<void>;
// }
//
// export interface FlowOptions {
//   prefetch: number;
// }
//
// export interface PushEngine {
//   attach(sink: ConsumerSink): void;
//   run(from: number): Promise<number>;
//   credits(consumerId: string): number;
// }

export function createPushEngine(log, options) {
    const sinks = [];
    /** Credit is per consumer, not one global pool */
    const credit = new Map();
    /** The push loop parks here when there is no credit */
    const waiting = [];
    function creditOf(id) {
        const value = credit.get(id);
        return value === undefined ? 0 : value;
    }
    function pickSink() {
        const ready = sinks.filter((sink) => creditOf(sink.id) > 0);
        return ready.length > 0 ? ready[0] : null;
    }
    function giveBack(id) {
        credit.set(id, creditOf(id) + 1);
        const next = waiting.shift();
        if (next)
            next();
    }
    function waitForCredit() {
        return new Promise((resolve) => {
            waiting.push(resolve);
        });
    }
    return {
        attach(sink) {
            sinks.push(sink);
            credit.set(sink.id, options.prefetch);
        },
        async run(from) {
            if (sinks.length === 0)
                return 0;
            const inFlight = [];
            let cursor = from;
            let pushed = 0;
            for (;;) {
                const records = log.read(cursor, 1);
                if (records.length === 0)
                    break;
                const record = records[0];
                let sink = pickSink();
                while (!sink) {
                    await waitForCredit();
                    sink = pickSink();
                }
                credit.set(sink.id, creditOf(sink.id) - 1);
                cursor = record.offset + 1;
                pushed += 1;
                const target = sink;
                // Push the next one without waiting for deliver: parallelism is set by credit, not by await
                inFlight.push(Promise.resolve()
                    .then(() => target.deliver(record))
                    // Credit has to be returned on failure too, or this consumer slowly leaks all of it away
                    .catch(() => undefined)
                    .then(() => giveBack(target.id)));
            }
            await Promise.all(inFlight);
            return pushed;
        },
        credits(consumerId) {
            return creditOf(consumerId);
        },
    };
}

