// Type contract for this file (TypeScript syntax, for reference):
//
// export interface MembershipOptions {
//   sessionTimeoutMs: number;
//   partitions: number;
// }
//
// export interface MembershipCoordinator {
//   join(memberId: string): void;
//   heartbeat(memberId: string): void;
//   leave(memberId: string): void;
//   tick(): number;
//   claim(memberId: string, offsets: number[]): void;
//   release(memberId: string, offset: number): void;
//   requeued(): number[];
//   members(): string[];
//   assignmentOf(memberId: string): number[];
// }

import { now } from '@lab/env';
export function createCoordinator(options) {
    const lastSeen = new Map();
    const assignment = new Map();
    const claimed = new Map();
    const back = [];
    function currentOwners() {
        const owner = new Map();
        for (const pair of Array.from(assignment.entries())) {
            for (const partition of pair[1])
                owner.set(partition, pair[0]);
        }
        return owner;
    }
    /**
     * How many each member should get: the quotient shared evenly, the remainder to those
     * earlier in the list
     */
    function targets(members) {
        const quota = new Map();
        if (members.length === 0)
            return quota;
        const base = Math.floor(options.partitions / members.length);
        const extra = options.partitions % members.length;
        members.forEach((member, index) => quota.set(member, base + (index < extra ? 1 : 0)));
        return quota;
    }
    function rebalance() {
        const members = Array.from(lastSeen.keys()).sort();
        const owner = currentOwners();
        const quota = targets(members);
        const next = new Map();
        for (const member of members)
            next.set(member, []);
        const orphans = [];
        for (let partition = 0; partition < options.partitions; partition += 1) {
            const holder = owner.get(partition);
            const kept = holder ? next.get(holder) : undefined;
            // If the current owner is still around and still short, let it keep them — this step
            // is what keeps shards from moving
            if (kept && kept.length < (quota.get(holder) || 0))
                kept.push(partition);
            else
                orphans.push(partition);
        }
        for (const partition of orphans) {
            const taker = members.filter((member) => (next.get(member) || []).length < (quota.get(member) || 0))[0];
            if (!taker)
                break;
            next.get(taker).push(partition);
        }
        let moved = 0;
        assignment.clear();
        for (const member of members) {
            const parts = next.get(member).sort((left, right) => left - right);
            for (const partition of parts) {
                if (owner.get(partition) !== member)
                    moved += 1;
            }
            assignment.set(member, parts);
        }
        return moved;
    }
    function evict(memberId) {
        // Unprocessed messages in hand go back to the queue rather than waiting out the
        // visibility timeout
        for (const offset of claimed.get(memberId) || [])
            back.push(offset);
        claimed.delete(memberId);
        lastSeen.delete(memberId);
        assignment.delete(memberId);
    }
    return {
        join(memberId) {
            lastSeen.set(memberId, now());
            rebalance();
        },
        heartbeat(memberId) {
            if (lastSeen.has(memberId))
                lastSeen.set(memberId, now());
        },
        leave(memberId) {
            evict(memberId);
            rebalance();
        },
        tick() {
            // Collect first, delete second: deleting while iterating quietly skips the next entry
            const expired = Array.from(lastSeen.entries())
                .filter((pair) => now() - pair[1] >= options.sessionTimeoutMs)
                .map((pair) => pair[0]);
            for (const memberId of expired)
                evict(memberId);
            return rebalance();
        },
        claim(memberId, offsets) {
            const held = claimed.get(memberId) || [];
            claimed.set(memberId, held.concat(offsets));
        },
        release(memberId, offset) {
            const held = claimed.get(memberId) || [];
            claimed.set(memberId, held.filter((item) => item !== offset));
        },
        requeued() {
            return back.slice();
        },
        members() {
            return Array.from(lastSeen.keys()).sort();
        },
        assignmentOf(memberId) {
            return (assignment.get(memberId) || []).slice();
        },
    };
}

