// Type contract for this file (TypeScript syntax, for reference):
//
// export interface QuotaOptions {
//   perWindow: number;
//   windowMs: number;
// }
//
// export interface FairScheduler {
//   submit(clientId: string, want: number): void;
//   dispatch(capacity: number): Record<string, number>;
//   remaining(clientId: string): number;
//   pending(clientId: string): number;
// }

import { now } from '@lab/env';
export function createFairScheduler(options) {
    const demand = new Map();
    /** How much has been taken in this window */
    const used = new Map();
    /** The client rotation order, joined on the first submit */
    const order = [];
    let windowStart = now();
    /** Which position the next round starts from — the whole secret of the fairness */
    let rotation = 0;
    function rollWindow() {
        if (now() < windowStart + options.windowMs)
            return;
        windowStart = now();
        used.clear();
    }
    function valueOf(table, clientId) {
        const value = table.get(clientId);
        return value === undefined ? 0 : value;
    }
    function allowance(clientId) {
        return options.perWindow - valueOf(used, clientId);
    }
    return {
        submit(clientId, want) {
            if (!demand.has(clientId))
                order.push(clientId);
            demand.set(clientId, valueOf(demand, clientId) + Math.max(0, want));
        },
        dispatch(capacity) {
            rollWindow();
            const granted = {};
            if (order.length === 0)
                return granted;
            let left = Math.max(0, capacity);
            let handed = 0;
            let servedSomeone = true;
            // Hand out one at a time, going round and round: every edge case disappears on its own
            while (left > 0 && servedSomeone) {
                servedSomeone = false;
                for (let step = 0; step < order.length && left > 0; step += 1) {
                    const clientId = order[(rotation + step) % order.length];
                    if (valueOf(demand, clientId) <= 0)
                        continue;
                    // Skip a client out of allowance, but keep handing capacity down the line rather
                    // than wasting it
                    if (allowance(clientId) <= 0)
                        continue;
                    granted[clientId] = (granted[clientId] || 0) + 1;
                    demand.set(clientId, valueOf(demand, clientId) - 1);
                    used.set(clientId, valueOf(used, clientId) + 1);
                    left -= 1;
                    handed += 1;
                    servedSomeone = true;
                }
            }
            // Advance the starting point so a different client leads the next round, which is how
            // those at the back get a turn
            rotation = (rotation + handed) % order.length;
            return granted;
        },
        remaining(clientId) {
            rollWindow();
            return Math.max(0, allowance(clientId));
        },
        pending(clientId) {
            return valueOf(demand, clientId);
        },
    };
}

