// Type contract for this file (TypeScript syntax, for reference):
//
// export interface BrokerOptions {
//   minInSync: number;
//   maxLagRecords: number;
//   visibilityMs: number;
//   maxAttempts: number;
//   baseBackoffMs: number;
// }
//
// export interface BrokerStats {
//   produced: number;
//   committed: number;
//   delivered: number;
//   acked: number;
//   inflight: number;
//   deadLetters: number;
//   backlog: number;
//   lag: number;
// }
//
// export interface Broker {
//   publish(key: string, value: string): Promise<number>;
//   poll(max: number): RetryDelivery[];
//   ack(receipt: string): boolean;
//   nack(receipt: string, reason: string): void;
//   stats(): BrokerStats;
// }

import { createDeliveryQueue } from './delivery';
import { createRetryingQueue } from './redelivery';
import { createReplicatedLog } from './replication';
export function createBroker(log, replicas, options) {
    const replicated = createReplicatedLog(log, replicas, {
        minInSync: options.minInSync,
        maxLagRecords: options.maxLagRecords,
    });
    /**
     * The log view the delivery side sees: reads stop at the high watermark.
     * Every method other than read forwards straight through — this layer holds no logic.
     */
    const visible = {
        append: (key, value) => log.append(key, value),
        read: (offset, max) => replicated.read(offset, max),
        endOffset: () => replicated.highWatermark(),
        segments: () => log.segments(),
        flush: () => log.flush(),
    };
    const source = createDeliveryQueue(visible, { visibilityMs: options.visibilityMs });
    const queue = createRetryingQueue(source, {
        visibilityMs: options.visibilityMs,
        maxAttempts: options.maxAttempts,
        baseBackoffMs: options.baseBackoffMs,
    });
    let produced = 0;
    let delivered = 0;
    let acked = 0;
    return {
        async publish(key, value) {
            const offset = await replicated.produce(key, value);
            produced += 1;
            return offset;
        },
        poll(max) {
            const batch = queue.poll(max);
            delivered += batch.length;
            return batch;
        },
        ack(receipt) {
            const done = queue.ack(receipt);
            // An invalid receipt completed nothing and must not increase the count
            if (done)
                acked += 1;
            return done;
        },
        nack(receipt, reason) {
            queue.nack(receipt, reason);
        },
        stats() {
            const dead = queue.deadLetters().length;
            // Completely done = acknowledged plus dead-lettered. Deliveries include redeliveries
            // and cannot be used to subtract.
            const finished = acked + dead;
            return {
                produced,
                committed: replicated.highWatermark(),
                delivered,
                acked,
                inflight: queue.inflight(),
                deadLetters: dead,
                backlog: Math.max(0, replicated.highWatermark() - finished),
                lag: Math.max(0, replicated.endOffset() - finished),
            };
        },
    };
}

