  });

  it('rejects an infinite self-application type', () => {
    const selfApplication: Expression = {
      kind: 'lambda',
      parameter: 'x',
      body: { kind: 'call', callee: variable('x'), argument: variable('x') },
    };
    expect(throws(selfApplication)).toBe(true);
  });
