// Type contract for this file (TypeScript syntax, for reference):
//
// export type Statement =
//   | { kind: 'var'; name: string; initializer?: Statement }
//   | { kind: 'use'; name: string }
//   | { kind: 'block'; statements: Statement[] };
//
// export interface ResolvedUse {
//   name: string;
//   bindingId: number;
//   depth: number;
// }
//
// export interface Resolution {
//   declarations: Array<{ name: string; bindingId: number }>;
//   uses: ResolvedUse[];
//   diagnostics: Array<{ kind: 'duplicate' | 'unresolved'; name: string }>;
// }

export function resolve(program) {
    const scopes = [];
    const declarations = [];
    const uses = [];
    const diagnostics = [];
    let nextBindingId = 1;
    function find(name) {
        for (let index = scopes.length - 1; index >= 0; index -= 1) {
            const bindingId = scopes[index].get(name);
            if (bindingId !== undefined)
                return { bindingId, depth: scopes.length - 1 - index };
        }
        return null;
    }
    function visit(statement) {
        if (statement.kind === 'block') {
            scopes.push(new Map());
            statement.statements.forEach(visit);
            scopes.pop();
            return;
        }
        if (statement.kind === 'use') {
            const binding = find(statement.name);
            if (binding)
                uses.push({ name: statement.name, ...binding });
            else
                diagnostics.push({ kind: 'unresolved', name: statement.name });
            return;
        }
        if (statement.initializer)
            visit(statement.initializer);
        const scope = scopes[scopes.length - 1];
        if (!scope)
            throw new Error('declaration outside a block');
        if (scope.has(statement.name)) {
            diagnostics.push({ kind: 'duplicate', name: statement.name });
            return;
        }
        const bindingId = nextBindingId;
        nextBindingId += 1;
        scope.set(statement.name, bindingId);
        declarations.push({ name: statement.name, bindingId });
    }
    visit(program);
    return { declarations, uses, diagnostics };
}

