// Type contract for this file (TypeScript syntax, for reference):
//
// export interface CfgBlock { id: string; successors: string[] }
//
// export interface CfgAnalysis {
//   reachable: string[];
//   predecessors: Record<string, string[]>;
//   dominators: Record<string, string[]>;
//   immediateDominators: Record<string, string | null>;
// }

export function analyzeCfg(entry, blocks) {
    const byId = new Map(blocks.map((block) => [block.id, block]));
    if (!byId.has(entry))
        throw new Error('missing entry ' + entry);
    for (const block of blocks) {
        for (const successor of block.successors) {
            if (!byId.has(successor))
                throw new Error('missing successor ' + successor);
        }
    }
    const seen = new Set();
    function visit(id) {
        if (seen.has(id))
            return;
        seen.add(id);
        byId.get(id).successors.forEach(visit);
    }
    visit(entry);
    const reachable = blocks.filter((block) => seen.has(block.id)).map((block) => block.id);
    const order = new Map(reachable.map((id, index) => [id, index]));
    const predecessors = {};
    reachable.forEach((id) => { predecessors[id] = []; });
    for (const id of reachable) {
        for (const successor of byId.get(id).successors) {
            if (seen.has(successor))
                predecessors[successor].push(id);
        }
    }
    const all = new Set(reachable);
    const dom = new Map();
    reachable.forEach((id) => dom.set(id, id === entry ? new Set([entry]) : new Set(all)));
    let changed = true;
    while (changed) {
        changed = false;
        for (const id of reachable) {
            if (id === entry)
                continue;
            const incoming = predecessors[id];
            let next = incoming.length ? new Set(dom.get(incoming[0])) : new Set();
            for (const predecessor of incoming.slice(1)) {
                const predecessorSet = dom.get(predecessor);
                next = new Set(Array.from(next).filter((item) => predecessorSet.has(item)));
            }
            next.add(id);
            const previous = dom.get(id);
            if (next.size !== previous.size || Array.from(next).some((item) => !previous.has(item))) {
                dom.set(id, next);
                changed = true;
            }
        }
    }
    const dominators = {};
    const immediateDominators = {};
    for (const id of reachable) {
        const sorted = Array.from(dom.get(id)).sort((a, b) => order.get(a) - order.get(b));
        dominators[id] = sorted;
        if (id === entry)
            immediateDominators[id] = null;
        else {
            const strict = sorted.filter((item) => item !== id);
            immediateDominators[id] = strict.find((candidate) => strict.every((other) => other === candidate || !dom.get(other).has(candidate))) || null;
        }
    }
    return { reachable, predecessors, dominators, immediateDominators };
}

