    space.map(0x1000, 0x9000, 1, rwUser);
    space.protect(0x1000, 1, rxUser);
    expect(throws(() => space.translate(0x1000, 'write', 'user'))).toBe(true);
    expect(space.translate(0x1000, 'execute', 'user')).toBe(0x9000);
