// Type contract for this file (TypeScript syntax, for reference):
//
// export interface MemoryRegion {
//   base: number;
//   length: number;
//   type: 'usable' | 'reserved' | 'device';
// }
//
// export interface FrameStats {
//   total: number;
//   free: number;
//   allocated: number;
//   reserved: number;
// }
//
// export interface FrameAllocator {
//   allocate(): number | null;
//   free(address: number): void;
//   reserve(address: number): void;
//   stats(): FrameStats;
// }

export function createFrameAllocator(regions, pageSize = 4096) {
    if (!Number.isInteger(pageSize) || pageSize <= 0)
        throw new Error('invalid page size');
    const all = new Set();
    for (const region of regions) {
        if (region.type !== 'usable' || region.length <= 0)
            continue;
        const start = Math.ceil(region.base / pageSize) * pageSize;
        const end = Math.floor((region.base + region.length) / pageSize) * pageSize;
        for (let address = start; address < end; address += pageSize)
            all.add(address);
    }
    const freeFrames = Array.from(all).sort((left, right) => left - right);
    const allocated = new Set();
    const reserved = new Set();
    function removeFree(address) {
        const index = freeFrames.indexOf(address);
        if (index < 0)
            return false;
        freeFrames.splice(index, 1);
        return true;
    }
    return {
        allocate() {
            const address = freeFrames.shift();
            if (address === undefined)
                return null;
            allocated.add(address);
            return address;
        },
        free(address) {
            if (!allocated.has(address))
                throw new Error('frame is not allocated');
            allocated.delete(address);
            freeFrames.push(address);
            freeFrames.sort((left, right) => left - right);
        },
        reserve(address) {
            if (!all.has(address))
                throw new Error('frame is outside usable memory');
            if (allocated.has(address))
                throw new Error('allocated frame cannot be reserved');
            if (reserved.has(address))
                return;
            if (!removeFree(address))
                throw new Error('frame is not free');
            reserved.add(address);
        },
        stats() {
            return {
                total: all.size,
                free: freeFrames.length,
                allocated: allocated.size,
                reserved: reserved.size,
            };
        },
    };
}

