        expect(allocator.allocate()).toBe(0);
        expect(allocator.allocate()).toBe(null);
    });
    it('reuses a freed frame in address order', () => {
        const allocator = createFrameAllocator([{ base: 0, length: 12288, type: 'usable' }]);
