// Type contract for this file (TypeScript syntax, for reference):
//
// export interface PagePermissions {
//   read: boolean;
//   write: boolean;
//   execute: boolean;
//   user: boolean;
// }
//
// export type AccessType = 'read' | 'write' | 'execute';
//
// export type CpuMode = 'user' | 'kernel';
//
// interface PageEntry {
//   physicalPage: number;
//   permissions: PagePermissions;
// }
//
// export interface AddressSpace {
//   map(virtualAddress: number, physicalAddress: number, pages: number, permissions: PagePermissions): void;
//   unmap(virtualAddress: number, pages: number): void;
//   protect(virtualAddress: number, pages: number, permissions: PagePermissions): void;
//   translate(address: number, access: AccessType, mode: CpuMode): number;
//   mappedPages(): number;
// }

export function createAddressSpace(options = {}) {
    const pageSize = options.pageSize || 4096;
    const userTop = options.userTop === undefined ? 0x80000000 : options.userTop;
    const entries = new Map();
    if (!Number.isInteger(pageSize) || pageSize <= 0)
        throw new Error('invalid page size');
    function aligned(address) {
        return Number.isInteger(address) && address >= 0 && address % pageSize === 0;
    }
    function validPermissions(permissions) {
        if (permissions.write && permissions.execute)
            throw new Error('write xor execute violation');
    }
    function pagesInRange(address, pages) {
        if (!aligned(address) || !Number.isInteger(pages) || pages <= 0)
            throw new Error('invalid page range');
        const first = address / pageSize;
        return Array.from({ length: pages }, (_, index) => first + index);
    }
    return {
        map(virtualAddress, physicalAddress, pages, permissions) {
            if (!aligned(physicalAddress))
                throw new Error('physical address is not aligned');
            validPermissions(permissions);
            if (permissions.user && virtualAddress + pages * pageSize > userTop) {
                throw new Error('user mapping crosses into kernel space');
            }
            const virtualPages = pagesInRange(virtualAddress, pages);
            if (virtualPages.some((page) => entries.has(page)))
                throw new Error('mapping overlaps an existing page');
            const physicalFirst = physicalAddress / pageSize;
            virtualPages.forEach((page, index) => {
                entries.set(page, { physicalPage: physicalFirst + index, permissions: { ...permissions } });
            });
        },
        unmap(virtualAddress, pages) {
            for (const page of pagesInRange(virtualAddress, pages))
                entries.delete(page);
        },
        protect(virtualAddress, pages, permissions) {
            validPermissions(permissions);
            const range = pagesInRange(virtualAddress, pages);
            if (permissions.user && virtualAddress + pages * pageSize > userTop) {
                throw new Error('user mapping crosses into kernel space');
            }
            if (range.some((page) => !entries.has(page)))
                throw new Error('cannot protect an unmapped page');
            range.forEach((page) => {
                const entry = entries.get(page);
                entries.set(page, { physicalPage: entry.physicalPage, permissions: { ...permissions } });
            });
        },
        translate(address, access, mode) {
            if (!Number.isInteger(address) || address < 0)
                throw new Error('invalid virtual address');
            const page = Math.floor(address / pageSize);
            const entry = entries.get(page);
            if (!entry)
                throw new Error('page fault: unmapped');
            if (mode === 'user' && !entry.permissions.user)
                throw new Error('page fault: supervisor page');
            if (!entry.permissions[access])
                throw new Error('page fault: permission denied');
            return entry.physicalPage * pageSize + (address % pageSize);
        },
        mappedPages() {
            return entries.size;
        },
    };
}

