// Type contract for this file (TypeScript syntax, for reference):
//
// export type TaskState = 'ready' | 'running' | 'blocked' | 'done';
//
// export interface TaskSnapshot {
//   id: string;
//   priority: number;
//   remainingTicks: number;
//   state: TaskState;
// }
//
// interface Task extends TaskSnapshot {}
//
// export interface Scheduler {
//   add(id: string, priority: number, ticks: number): void;
//   tick(): string | null;
//   block(id: string): void;
//   wake(id: string): void;
//   current(): string | null;
//   snapshot(): TaskSnapshot[];
// }

export function createScheduler(options) {
    if (!Number.isInteger(options.quantum) || options.quantum <= 0)
        throw new Error('invalid quantum');
    const tasks = new Map();
    const ready = new Map();
    let currentId = null;
    let slice = 0;
    function enqueue(task) {
        if (task.state === 'done')
            return;
        const queue = ready.get(task.priority) || [];
        if (!queue.includes(task.id))
            queue.push(task.id);
        ready.set(task.priority, queue);
        task.state = 'ready';
    }
    function removeFromReady(id) {
        for (const [priority, queue] of Array.from(ready.entries())) {
            const filtered = queue.filter((item) => item !== id);
            if (filtered.length)
                ready.set(priority, filtered);
            else
                ready.delete(priority);
        }
    }
    function highestReadyPriority() {
        const priorities = Array.from(ready.entries())
            .filter((entry) => entry[1].length > 0)
            .map((entry) => entry[0]);
        return priorities.length ? Math.max(...priorities) : null;
    }
    function takeNext() {
        const priority = highestReadyPriority();
        if (priority === null)
            return null;
        const queue = ready.get(priority);
        const id = queue.shift();
        if (queue.length === 0)
            ready.delete(priority);
        const task = tasks.get(id);
        task.state = 'running';
        return task;
    }
    function schedule() {
        if (currentId) {
            const running = tasks.get(currentId);
            const highest = highestReadyPriority();
            if (highest !== null && highest > running.priority) {
                enqueue(running);
                currentId = null;
                slice = 0;
            }
        }
        if (!currentId) {
            const next = takeNext();
            if (!next)
                return null;
            currentId = next.id;
            slice = 0;
        }
        return tasks.get(currentId);
    }
    return {
        add(id, priority, ticks) {
            if (tasks.has(id))
                throw new Error('duplicate task id');
            if (!id || !Number.isFinite(priority) || !Number.isInteger(ticks) || ticks <= 0) {
                throw new Error('invalid task');
            }
            const task = { id, priority, remainingTicks: ticks, state: 'ready' };
            tasks.set(id, task);
            enqueue(task);
        },
        tick() {
            const task = schedule();
            if (!task)
                return null;
            task.remainingTicks -= 1;
            slice += 1;
            const ran = task.id;
            if (task.remainingTicks === 0) {
                task.state = 'done';
                currentId = null;
                slice = 0;
            }
            else if (slice >= options.quantum) {
                enqueue(task);
                currentId = null;
                slice = 0;
            }
            return ran;
        },
        block(id) {
            const task = tasks.get(id);
            if (!task || task.state === 'done')
                throw new Error('task cannot be blocked');
            removeFromReady(id);
            if (currentId === id) {
                currentId = null;
                slice = 0;
            }
            task.state = 'blocked';
        },
        wake(id) {
            const task = tasks.get(id);
            if (!task)
                throw new Error('unknown task');
            if (task.state === 'blocked')
                enqueue(task);
        },
        current() {
            return currentId;
        },
        snapshot() {
            return Array.from(tasks.values())
                .map((task) => ({ ...task }))
                .sort((left, right) => left.id.localeCompare(right.id));
        },
    };
}

