// Type contract for this file (TypeScript syntax, for reference):
//
// export interface DeadlineOptions {
//   concurrency?: number;
//   timeoutMs: number;
//   totalBudgetMs?: number;
//   signal?: CancelToken;
// }

import { now, sleep } from '@lab/env';
import { request } from '@lab/net';
/**
 * The timeout branch returns a sentinel instead of throwing, so one check after the race
 * separates the two paths
 */
const TIMED_OUT = Symbol('timed-out');
export async function fetchWithDeadline(urls, options) {
    const results = new Array(urls.length);
    if (urls.length === 0)
        return results;
    // Record the budget as an absolute instant: simpler than tracking how much is left, and
    // correct under concurrency
    const deadline = options.totalBudgetMs === undefined ? Infinity : now() + options.totalBudgetMs;
    const size = Math.max(1, Math.min(options.concurrency ?? 1, urls.length));
    let cursor = 0;
    function outOfTime() {
        return now() >= deadline || Boolean(options.signal?.cancelled);
    }
    async function runOne(index) {
        const url = urls[index];
        const outcome = await Promise.race([
            request(url).then((response) => response.data),
            sleep(options.timeoutMs).then(() => TIMED_OUT),
        ]);
        // Return as soon as the race settles; the slot is released when this function returns.
        // Awaiting the abandoned request here would make the timeout pointless
        if (outcome === TIMED_OUT) {
            results[index] = { url, ok: false, data: null, error: 'timeout' };
            return;
        }
        results[index] = { url, ok: true, data: outcome };
    }
    async function worker() {
        for (;;) {
            // Re-check on every take: the batch started concurrently may exhaust the budget part-way
            if (cursor >= urls.length)
                return;
            const index = cursor;
            cursor += 1;
            if (outOfTime()) {
                results[index] = {
                    url: urls[index],
                    ok: false,
                    data: null,
                    error: options.signal?.cancelled ? 'cancelled' : 'budget exhausted',
                };
                continue;
            }
            try {
                await runOne(index);
            }
            catch (error) {
                results[index] = {
                    url: urls[index],
                    ok: false,
                    data: null,
                    error: error instanceof Error ? error.message : String(error),
                };
            }
        }
    }
    const runners = [];
    for (let slot = 0; slot < size; slot += 1)
        runners.push(worker());
    await Promise.all(runners);
    return results;
}

