// Type contract for this file (TypeScript syntax, for reference):
//
// export interface HedgeOptions {
//   hedgeAfterMs: number;
//   maxAttempts?: number;
// }

import { sleep } from '@lab/env';
import { request } from '@lab/net';
export function hedgedFetch(replicas, options) {
    const limit = Math.min(options.maxAttempts ?? replicas.length, replicas.length);
    if (limit === 0) {
        return Promise.resolve({
            url: '',
            ok: false,
            data: null,
            error: 'no replicas to try',
        });
    }
    return new Promise((resolve) => {
        let settled = false;
        let launched = 0;
        let failures = 0;
        let lastError = 'all replicas failed';
        function finish(result) {
            if (settled)
                return;
            settled = true;
            resolve(result);
        }
        function launch(index) {
            // Check this first when the timer fires: the primary may have returned before it.
            // Without this line, a healthy system keeps generating double the traffic for nothing
            if (settled || index >= limit)
                return;
            launched += 1;
            const url = replicas[index];
            request(url).then((response) => finish({ url, ok: true, data: response.data }), (error) => {
                failures += 1;
                lastError = error instanceof Error ? error.message : String(error);
                // Only 'everything already sent has failed and nothing more will be sent' counts
                // as a real failure.
                // A Promise.race implementation calls it a day on the first failure
                if (failures === launched && launched >= limit) {
                    finish({ url, ok: false, data: null, error: lastError });
                }
                else if (failures === launched) {
                    // Nothing is in flight any more, so send the next one now rather than waiting
                    // out hedgeAfterMs
                    launch(launched);
                }
            });
            if (index + 1 < limit) {
                sleep(options.hedgeAfterMs).then(() => launch(index + 1));
            }
        }
        launch(0);
    });
}

