export class CancelledError extends Error {
    constructor() {
        super('operation cancelled');
        this.name = 'CancelledError';
    }
}
export function createCancelSource() {
    let cancelled = false;
    const listeners = [];
    const token = {
        get cancelled() {
            return cancelled;
        },
        throwIfCancelled() {
            if (cancelled)
                throw new CancelledError();
        },
        onCancel(listener) {
            if (cancelled)
                listener();
            else
                listeners.push(listener);
        },
    };
    return {
        token,
        cancel() {
            if (cancelled)
                return;
            cancelled = true;
            listeners.splice(0).forEach((listener) => listener());
        },
    };
}

// Type contract for this file (TypeScript syntax, for reference):
//
// export interface PipelineStats {
//   completed: number;
//   failed: number;
//   cacheHits: number;
// }
//
// export interface Pipeline {
//   run(urls: string[]): Promise<PageResult[]>;
//   stats(): PipelineStats;
// }
//
// export interface PipelineOptions extends FetchOptions {
//   signal?: CancelToken;
// }

/**
